1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { canAccess } from "./rbac";
9	import { sendMail, emails } from "./mailer";
10	
11	/**
12	 * SUPPORT-ROLE ENFORCEMENT (2026-07-27 admin audit).
13	 *
14	 * `lib/rbac.ts` grants the `support` area to SUPPORT and ADMIN, `/admin/support`
15	 * and `/admin/support/[id]` both gate on `requireArea("support")`, and the admin
16	 * layout renders the desk in a SUPPORT agent's sidebar. Every WRITE behind those
17	 * pages, however, still required ADMIN:
18	 *
19	 *   - `setTicketPriority` called `requireAdmin()`. `PrioritySelect` does not
20	 *     catch, so a SUPPORT agent picked "Urgent", the throw vanished into an
21	 *     unhandled transition, and the `<select>` (uncontrolled, `defaultValue`)
22	 *     kept showing the new value. The control reported success and did nothing.
23	 *   - `setTicketStatus` and `replyTicket` applied the CUSTOMER ownership test
24	 *     (`ticket.userId !== user.id && role !== "ADMIN"`), so a SUPPORT agent could
25	 *     neither close nor answer a ticket that was not their own — i.e. any ticket.
26	 *
27	 * So the entire job of the SUPPORT role was a read-only page with three controls
28	 * that silently refused. `lib/actions-chat.ts` — the other half of the same area —
29	 * has always gated correctly on `requireArea("support")`; the ticket desk simply
30	 * was never updated when RBAC landed. These now use the same rule. No role gains
31	 * anything `lib/rbac.ts` did not already declare, and CUSTOMER is unaffected:
32	 * a customer still reaches only their own ticket.
33	 */
34	/**
35	 * The session behind a ticket action, plus whether they are support staff.
36	 *
37	 * Named `require*` deliberately. `test/auth-lockouts.test.ts` enforces that every
38	 * export of a "use server" file — each of which is a network-callable endpoint
39	 * anyone can POST to — calls a recognised guard INSIDE the function, and it
40	 * recognises guards by the `require*`/`owned*`/`assert*`/`resolve*` convention.
41	 * This helper was `ticketActor`, which guarded correctly but did not LOOK like a
42	 * guard, so the tripwire reported three genuinely-safe endpoints as unguarded.
43	 *
44	 * The fix was the name, not the rule: widening the rule to accept arbitrary
45	 * helper names would let a future function that guards nothing pass the same
46	 * check. A guard should be recognisable as one.
47	 */
48	async function requireTicketActor(): Promise<{ id: string; isSupportStaff: boolean }> {
49	  const user = await requireUser();
50	  return { id: user.id, isSupportStaff: canAccess(user.role, "support") };
51	}
52	
53	export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
54	  const user = await requireUser();
55	  const parsed = z
56	    .object({
57	      subject: z.string().min(3).max(150),
58	      body: z.string().min(5).max(10000),
59	      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
60	    })
61	    .safeParse({
62	      subject: formData.get("subject"),
63	      body: formData.get("body"),
64	      priority: formData.get("priority") ?? "NORMAL",
65	    });
66	  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };
67	
68	  const ticket = await db.ticket.create({
69	    data: {
70	      subject: parsed.data.subject,
71	      priority: parsed.data.priority,
72	      userId: user.id,
73	      messages: { create: { body: parsed.data.body, authorId: user.id, isStaff: false } },
74	    },
75	  });
76	  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
77	  await db.notification.createMany({
78	    data: admins.map((a) => ({
79	      userId: a.id,
80	      title: `New ticket: ${parsed.data.subject}`,
81	      href: `/admin/support/${ticket.id}`,
82	    })),
83	  });
84	  redirect(`/dashboard/support/${ticket.id}`);
85	}
86	
87	export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
88	  const user = await requireTicketActor();
89	  const ticketId = String(formData.get("ticketId") ?? "");
90	  const body = String(formData.get("body") ?? "").trim();
91	  if (body.length < 2 || body.length > 10000) return { error: "Message too short." };
92	
93	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
94	  if (!ticket) return { error: "Ticket not found." };
95	  const isStaff = user.isSupportStaff && ticket.userId !== user.id;
96	  if (ticket.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };
97	
98	  await db.$transaction([
99	    db.ticketMessage.create({ data: { ticketId, body, authorId: user.id, isStaff } }),
100	    db.ticket.update({
101	      where: { id: ticketId },
102	      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
103	    }),
104	  ]);
105	
106	  if (isStaff) {
107	    await db.notification.create({
108	      data: {
109	        userId: ticket.userId,
110	        title: `Support replied: ${ticket.subject}`,
111	        href: `/dashboard/support/${ticketId}`,
112	      },
113	    });
114	    // Also EMAIL the customer the staff reply — an in-app bell alone is easy to
115	    // miss. Best-effort: a mail failure must never fail the reply itself.
116	    try {
117	      const customer = await db.user.findUnique({ where: { id: ticket.userId }, select: { email: true } });
118	      if (customer?.email) {
119	        const tpl = emails.ticketReply({
120	          ticketId,
121	          subject: ticket.subject,
122	          replyPreview: body,
123	        });
124	        await sendMail({
125	          to: customer.email,
126	          subject: tpl.subject,
127	          html: tpl.html,
128	          template: tpl.template,
129	          userId: ticket.userId,
130	          kind: "support_reply",
131	        });
132	      }
133	    } catch (e) {
134	      console.error("[support] staff-reply email failed (non-fatal)", e);
135	    }
136	  } else {
137	    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
138	    await db.notification.createMany({
139	      data: admins.map((a) => ({
140	        userId: a.id,
141	        title: `Ticket reply: ${ticket.subject}`,
142	        href: `/admin/support/${ticketId}`,
143	      })),
144	    });
145	  }
146	  revalidatePath(`/dashboard/support/${ticketId}`);
147	  revalidatePath(`/admin/support/${ticketId}`);
148	  return {};
149	}
150	
151	/**
152	 * A TypeScript parameter type is a compile-time comment on a network endpoint.
153	 *
154	 * Every export of this file is POST-able with any JSON the caller likes, so the
155	 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
156	 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
157	 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
158	 * the support queue's "needs a reply" view without anyone having replied. Values
159	 * outside the enum reached Prisma and threw, which surfaces as a server error
160	 * page rather than a message. Both are fixed by validating at the boundary.
161	 */
162	const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
163	const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;
164	
165	export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
166	  const user = await requireTicketActor();
167	  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
168	    throw new Error("A ticket can only be reopened or closed from here.");
169	  }
170	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
171	  if (!ticket) throw new Error("Not found");
172	  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
173	  await db.ticket.update({ where: { id: ticketId }, data: { status } });
174	  revalidatePath(`/dashboard/support`);
175	  revalidatePath(`/dashboard/support/${ticketId}`);
176	  revalidatePath(`/admin/support`);
177	  revalidatePath(`/admin/support/${ticketId}`);
178	}
179	
180	export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
181	  const user = await requireTicketActor();
182	  // Triage is a staff-only judgement — a customer must not be able to promote
183	  // their own ticket to URGENT — but it IS the support desk's job.
184	  if (!user.isSupportStaff) throw new Error("Forbidden");
185	  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
186	    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
187	  }
188	  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
189	  revalidatePath(`/admin/support`);
190	  revalidatePath(`/admin/support/${ticketId}`);
191	}
