172	// ---------------------------------------------------------------------------
173	// PUBLIC tools — available to EVERY visitor (signed in or not). These never
174	// touch a specific customer's private data, so they need no userId scoping.
175	// ---------------------------------------------------------------------------
176	export const PUBLIC_TOOLS: ClaudeToolDef[] = [
177	  {
178	    name: "check_platform_status",
179	    description:
180	      "Check Nxeon's LIVE platform status for any ongoing incident, outage, or " +
181	      "maintenance, plus any active operational announcement. Call this whenever a " +
