222	// ---------------------------------------------------------------------------
223	// Executor
224	// ---------------------------------------------------------------------------
225	
226	/**
227	 * Execute a tool STRICTLY scoped to `userId`. Read-only. Returns a concise,
228	 * model-friendly string. Never returns another user's data. On an unknown tool
229	 * or any error, returns a short error string (never throws).
230	 */
231	export async function runAccountTool(
232	  userId: string,
233	  name: string,
234	  input: unknown,
235	): Promise<string> {
236	  try {
237	    if (!userId) return "Error: no signed-in customer.";
238	    const currency = await currentCurrency();
239	    const money = (cents: number) => formatMoney(cents, currency);
240	
241	    switch (name) {
242	      case "get_account_overview":
243	        return await accountOverview(userId, money);
244	      case "list_services":
245	        return await listServices(userId);
246	      case "get_service":
247	        return await getService(userId, input);
248	      case "list_invoices":
249	        return await listInvoices(userId, input, money);
250	      case "get_billing_status":
251	        return await billingStatus(userId, money);
252	      case "list_tickets":
253	        return await listTickets(userId);
254	      case "open_support_ticket":
255	        return await openTicket(userId, input);
256	      default:
257	        return `Error: unknown tool "${name}".`;
258	    }
259	  } catch (err) {
260	    const msg = err instanceof Error ? err.message : String(err);
261	    return `Error running ${name}: ${msg}`;
262	  }
263	}
264	
265	/** The tools a given visitor may use: everyone gets PUBLIC_TOOLS; a signed-in
266	 *  customer additionally gets the account (read + open-ticket) tools. */
267	export function chatToolsFor(userId: string | null | undefined): ClaudeToolDef[] {
268	  return userId ? [...PUBLIC_TOOLS, ...ACCOUNT_TOOLS] : [...PUBLIC_TOOLS];
269	}
270	
271	const PUBLIC_TOOL_NAMES = new Set(PUBLIC_TOOLS.map((t) => t.name));
272	
273	/**
274	 * Unified executor for the chat agent. Routes public tools to the unscoped
275	 * runner and account tools to the userId-scoped runner. An account tool
276	 * requested without a signed-in user returns a gentle "please sign in" string
277	 * (never throws, never leaks). Read-only except open_support_ticket, which only
278	 * ever creates a ticket owned BY the calling customer.
279	 */
280	export async function runChatTool(
281	  userId: string | null | undefined,
282	  name: string,
283	  input: unknown,
284	): Promise<string> {
285	  if (PUBLIC_TOOL_NAMES.has(name)) return runPublicTool(name, input);
286	  if (!userId) {
287	    return "This looks up a specific customer's account, which needs them signed in. Ask the visitor to sign in at /login (or create an account at /register) and reopen chat there, and their account details will be available.";
288	  }
289	  return runAccountTool(userId, name, input);
290	}
291	
292	/** Execute a PUBLIC tool (no customer scoping needed). Never throws. */
293	export async function runPublicTool(name: string, input: unknown): Promise<string> {
294	  try {
295	    switch (name) {
296	      case "check_platform_status":
297	        return await platformStatus();
298	      case "get_plans":
299	        return planCatalog(input);
300	      case "search_help":
301	        return await searchHelp(input);
302	      default:
303	        return `Error: unknown tool "${name}".`;
304	    }
305	  } catch (err) {
306	    const msg = err instanceof Error ? err.message : String(err);
307	    return `Error running ${name}: ${msg}`;
308	  }
309	}
