311	// ---------------------------------------------------------------------------
312	// Tool implementations (each scoped to userId)
313	// ---------------------------------------------------------------------------
314	
315	async function accountOverview(userId: string, money: (c: number) => string): Promise<string> {
316	  const now = new Date();
317	  const [user, servers, hosting, emailSubs, domains, volumes, openInvoices, openTickets] =
318	    await Promise.all([
319	      db.user.findUnique({
320	        where: { id: userId },
321	        select: {
322	          balanceCents: true,
323	          signupCreditCents: true,
324	          cardBrand: true,
325	          cardLast4: true,
326	          cardExpMonth: true,
327	          cardExpYear: true,
328	          stripeCustomerId: true,
329	          stripePaymentMethodId: true,
330	        },
331	      }),
332	      db.server.findMany({
333	        where: { userId, status: { not: "DELETING" } },
334	        select: { status: true, gamePlanId: true, nxcloudInstance: { select: { id: true } } },
335	      }),
336	      db.hostingAccount.groupBy({
337	        by: ["status"],
338	        where: { userId, status: { not: "DELETING" } },
339	        _count: true,
340	      }),
341	      db.emailSubscription.count({ where: { userId } }),
342	      db.domain.count({ where: { userId } }),
343	      db.volume.count({ where: { userId, status: { not: "DELETING" } } }),
344	      db.invoice.findMany({
345	        where: { userId, status: "OPEN" },
346	        select: { amountCents: true },
347	      }),
348	      db.ticket.count({ where: { userId, status: { in: OPEN_TICKET_STATUSES } } }),
349	    ]);
350	
351	  if (!user) return "Error: customer not found.";
352	
353	  // Server breakdown by type + status.
354	  const vps = servers.filter((s) => !s.gamePlanId && !s.nxcloudInstance);
355	  const game = servers.filter((s) => s.gamePlanId && !s.nxcloudInstance);
356	  const nxcloud = servers.filter((s) => s.nxcloudInstance);
