844	/** Open a new support ticket owned by this customer (the one write action). */
845	async function openTicket(userId: string, input: unknown): Promise<string> {
846	  const obj = (typeof input === "object" && input ? input : {}) as Record<string, unknown>;
847	  const subject = typeof obj.subject === "string" ? obj.subject.trim().slice(0, 200) : "";
848	  const body = typeof obj.body === "string" ? obj.body.trim().slice(0, 5000) : "";
849	  const priority = typeof obj.priority === "string" && TICKET_PRIORITIES.has(obj.priority.toUpperCase())
850	    ? (obj.priority.toUpperCase() as "LOW" | "NORMAL" | "HIGH" | "URGENT")
851	    : "NORMAL";
852	  if (!subject || !body) return "Error: open_support_ticket needs both a subject and a body.";
853	
854	  // Guard against duplicate/spam tickets from one chat: cap open tickets.
855	  const openCount = await db.ticket.count({
856	    where: { userId, status: { in: OPEN_TICKET_STATUSES } },
857	  });
858	  if (openCount >= 8) {
859	    return "This customer already has several open tickets — do not open another; point them to /dashboard/support to follow up on an existing one.";
860	  }
861	
862	  const ticket = await db.ticket.create({
863	    data: {
864	      userId,
865	      subject,
866	      priority,
867	      messages: { create: { authorId: userId, body, isStaff: false } },
868	    },
869	    select: { id: true },
870	  });
871	  return lines(
872	    `Opened support ticket [${ticket.id}] "${subject}" (priority ${priority}).`,
873	    "Tell the customer it's been created and they can follow it at /dashboard/support; the team will reply there and by email.",
874	  );
875	}
