957	/** Full-text search over the indexed help/FAQ/blog content (KbChunk). Kept local
958	 *  to avoid a cyclic import with lib/kb.ts. Returns snippets for the model to
959	 *  synthesize — the model must rewrite them, never paste them verbatim. */
960	async function searchHelp(input: unknown): Promise<string> {
961	  const query =
962	    typeof input === "object" && input && typeof (input as { query?: unknown }).query === "string"
963	      ? (input as { query: string }).query.trim()
964	      : "";
965	  if (query.length < 3) return "Provide a longer search query.";
966	  let rows: { source: string; title: string; url: string | null; snippet: string }[] = [];
967	  try {
968	    rows = await db.$queryRaw<{ source: string; title: string; url: string | null; snippet: string }[]>`
969	      SELECT source, title, url, snippet
970	      FROM "KbChunk"
971	      WHERE to_tsvector('english', title || ' ' || content) @@ websearch_to_tsquery('english', ${query})
972	      ORDER BY ts_rank(to_tsvector('english', title || ' ' || content),
973	                       websearch_to_tsquery('english', ${query})) DESC
974	      LIMIT 4`;
975	  } catch {
976	    return "Help search is unavailable right now — answer from the core knowledge base instead.";
977	  }
978	  if (!rows.length) return `No help articles matched "${query}". Answer from the core knowledge base, or offer to open a ticket.`;
979	  return lines(
980	    `HELP RESULTS for "${query}" (synthesize into your own words — do NOT paste verbatim, and only cite a link if it directly answers):`,
981	    ...rows.map((r) => `• ${r.title}${r.url ? ` (${r.url})` : ""}\n${r.snippet.slice(0, 400)}`),
982	  );
983	}
