132	/**
133	 * Staff reply: append an "agent" message, flag the thread unread for the user,
134	 * clear the agent-unread flag, and assign it to the replying staff member.
135	 */
136	export async function replyToConversation(
137	  id: string,
138	  body: string
139	): Promise<{ error?: string; ok?: boolean }> {
140	  const staff = await requireArea("support");
141	
142	  const parsed = z
143	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
144	    .safeParse({ id, body });
145	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
146	
147	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
148	  if (!convo) return { error: "Conversation not found." };
149	
150	  await db.$transaction([
151	    db.chatMessage.create({
152	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
153	    }),
154	    db.chatConversation.update({
155	      where: { id: parsed.data.id },
156	      data: {
157	        status: "OPEN",
158	        unreadForUser: true,
159	        unreadForAgent: false,
160	        assignedToId: staff.id,
161	        lastMessageAt: new Date(),
162	      },
163	    }),
164	  ]);
165	
166	  // If the visitor is a signed-in customer, drop them a notification.
167	  if (convo.userId) {
168	    await db.notification
169	      .create({
170	        data: {
171	          userId: convo.userId,
172	          title: "New reply in your live chat",
173	          href: "/dashboard",
174	        },
175	      })
176	      .catch(() => {});
177	  }
178	
179	  revalidatePath("/admin/chat");
180	  return { ok: true };
181	}
