183	/**
184	 * Staff reply carrying an image attachment. Same authorization and side effects
185	 * as `replyToConversation` (requireArea("support"), notify, assign, unread) but
186	 * the message body may be empty and it stores a signature-verified image in
187	 * Postgres. All security checks (allow-list, magic-number, 5 MB cap, SVG
188	 * rejection) run in `validateImageBytes` — the client cannot bypass them.
189	 */
190	export async function replyWithAttachment(
191	  formData: FormData
192	): Promise<{ error?: string; ok?: boolean }> {
193	  const staff = await requireArea("support");
194	
195	  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
196	  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
197	  if (!rl.ok) return { error: "Too many uploads. Please slow down." };
198	
199	  const id = formData.get("conversationId");
200	  const rawBody = formData.get("body");
201	  const file = formData.get("file");
202	
203	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
204	  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
205	  if (!(file instanceof File)) return { error: "No image provided." };
206	  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };
207	
208	  const convo = await db.chatConversation.findUnique({ where: { id } });
209	  if (!convo) return { error: "Conversation not found." };
210	
211	  const bytes = Buffer.from(await file.arrayBuffer());
212	  const check = validateImageBytes(bytes, file.type);
213	  if (!check.ok) return { error: check.error };
214	
215	  await db.$transaction(async (tx) => {
216	    const msg = await tx.chatMessage.create({
217	      data: { conversationId: id, sender: "agent", body },
218	    });
219	    await tx.chatAttachment.create({
220	      data: {
221	        messageId: msg.id,
222	        mime: check.mime,
223	        sizeBytes: check.bytes.length,
224	        data: new Uint8Array(check.bytes),
225	      },
226	    });
227	    await tx.chatConversation.update({
228	      where: { id },
229	      data: {
230	        status: "OPEN",
231	        unreadForUser: true,
232	        unreadForAgent: false,
233	        assignedToId: staff.id,
234	        lastMessageAt: new Date(),
235	      },
236	    });
237	  });
238	
239	  if (convo.userId) {
240	    await db.notification
241	      .create({
242	        data: {
243	          userId: convo.userId,
244	          title: "New reply in your live chat",
245	          href: "/dashboard",
246	        },
247	      })
248	      .catch(() => {});
249	  }
250	
251	  revalidatePath("/admin/chat");
252	  return { ok: true };
253	}
