42	/** Extract a hidden `[[cards: key1, key2]]` directive from a bot reply, returning
43	 *  the visible body (directive stripped) and the card keys. */
44	function parseCardDirective(reply: string): { body: string; keys: string[] } {
45	  const m = reply.match(/\[\[\s*cards?\s*:\s*([^\]]+)\]\]/i);
46	  if (!m) return { body: reply, keys: [] };
47	  const keys = m[1]
48	    .split(",")
49	    .map((s) => s.trim())
50	    .filter(Boolean);
51	  const body = reply.replace(m[0], "").replace(/\n{3,}/g, "\n\n").trim();
52	  return { body, keys };
53	}
