55	/** One parsed (not-yet-resolved) `[[action: type=…, id=…, label="…"]]` spec. */
56	type ActionSpec = { kind: string; id: string; label?: string };
57	
58	/** Extract every hidden `[[action: ...]]` directive from a bot reply — the
59	 *  account-action-card sibling of `[[cards: ...]]` (see lib/kb-tools.ts's
60	 *  resolveActionCard for what these become). Attribute order doesn't matter;
61	 *  unrecognized attributes are ignored. Directives are stripped from the
62	 *  visible body regardless of whether they end up resolving to a real card. */
63	function parseActionDirectives(reply: string): { body: string; specs: ActionSpec[] } {
64	  const specs: ActionSpec[] = [];
65	  const re = /\[\[\s*action\s*:\s*([^\]]+)\]\]/gi;
66	  const body = reply
67	    .replace(re, (_full, attrsRaw: string) => {
68	      const attrs: Record<string, string> = {};
69	      // key=value pairs, comma-separated; value optionally double-quoted.
70	      const attrRe = /(\w+)\s*=\s*(?:"([^"]*)"|([^,]+))/g;
71	      let am: RegExpExecArray | null;
72	      while ((am = attrRe.exec(attrsRaw)) !== null) {
73	        attrs[am[1].toLowerCase()] = (am[2] ?? am[3] ?? "").trim();
74	      }
75	      if (attrs.type && attrs.id) {
76	        specs.push({ kind: attrs.type.toLowerCase(), id: attrs.id, label: attrs.label });
77	      }
78	      return "";
79	    })
80	    .replace(/\n{3,}/g, "\n\n")
81	    .trim();
82	  return { body, specs };
83	}
