108	    data: { botEscalatedAt: new Date(), unreadForAgent: true },
109	  });
110	  if (claim.count !== 1) return; // someone/something already escalated
111	
112	  await db.chatMessage.create({
113	    data: { conversationId: convo.id, sender: "bot", body: WAIT_MSG },
114	  });
