120	      if (to) {
121	        const who = convo.name
122	          ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
123	          : convo.email || "A website visitor";
124	        const html = layout(
125	          "A visitor wants to talk to a human",
126	          `<p><strong>${esc(who)}</strong> is asking for a live agent in the website chat.</p>
127	           <p style="color:#64748b">Latest message: “${esc(lastBody.slice(0, 300))}”</p>
128	           <p>Hop in within the next few minutes to take over — after that they'll be offered a callback instead.</p>
129	           ${button(ADMIN_CHAT_URL, "Open the live chat inbox")}`,
130	        );
131	        await sendMail({
132	          to,
133	          subject: "🔔 Live chat — a visitor wants a human",
134	          html,
135	          replyTo: convo.email || undefined,
136	        });
