144	/**
145	 * If a conversation is waiting on a human and the window has elapsed with no
146	 * agent, post the "no agents available" fallback and clear the waiting state.
147	 * Atomic (updateMany claim) so concurrent polls can't double-post. Safe to call
148	 * on every message and every GET poll.
149	 */
150	export async function checkEscalationTimeout(conversationId: string): Promise<void> {
151	  try {
152	    const convo = await db.chatConversation.findUnique({
153	      where: { id: conversationId },
154	      select: { id: true, botEscalatedAt: true, assignedToId: true },
155	    });
156	    if (!convo?.botEscalatedAt) return;
157	
158	    // An agent joined (assigned or replied) — drop the waiting state, no fallback.
159	    const agentReplies = await db.chatMessage.count({
160	      where: { conversationId, sender: "agent" },
161	    });
162	    if (agentReplies > 0 || convo.assignedToId) {
163	      await db.chatConversation.updateMany({
164	        where: { id: conversationId, botEscalatedAt: { not: null } },
165	        data: { botEscalatedAt: null },
166	      });
167	      return;
168	    }
169	
170	    const windowSec = await getSettingInt("kb_bot_window_sec", 180);
171	    const threshold = new Date(Date.now() - windowSec * 1000);
172	    // Claim the timeout: only one caller wins, and only once the window passed.
173	    const claim = await db.chatConversation.updateMany({
174	      where: { id: conversationId, botEscalatedAt: { not: null, lte: threshold }, assignedToId: null },
175	      data: { botEscalatedAt: null },
176	    });
177	    if (claim.count !== 1) return;
178	
179	    await db.chatMessage.create({
180	      data: { conversationId, sender: "bot", body: NO_AGENT_MSG },
181	    });
182	  } catch {
183	    /* non-essential */
184	  }
185	}
