187	/**
188	 * Evaluate the assistant for a just-received visitor message. Creates a bot
189	 * reply (or runs the handoff flow) when appropriate. `images` are the base64
190	 * blocks for an image the visitor just sent (upload path), if any.
191	 */
192	export async function runAssistant(args: {
193	  conversationId: string;
194	  visitorId: string;
195	  currentBody: string;
196	  images?: LlmImage[];
197	}): Promise<void> {
198	  try {
199	    if ((await getSetting("kb_bot_enabled", "false")) !== "true") return;
200	
201	    const convo = await db.chatConversation.findUnique({
202	      where: { id: args.conversationId },
203	      select: {
204	        id: true,
205	        visitorId: true,
206	        userId: true,
207	        name: true,
208	        email: true,
209	        assignedToId: true,
210	        botEscalatedAt: true,
211	        messages: { orderBy: { createdAt: "asc" }, select: { sender: true, body: true } },
212	      },
213	    });
214	    if (!convo) return;
215	
216	    // Never talk over a human: silent once an agent replied or was assigned.
217	    const agentReplied = convo.messages.some((m) => m.sender === "agent");
218	    if (agentReplied || convo.assignedToId) return;
219	
220	    // Already waiting on a live agent — stay quiet; just check the timeout.
221	    if (convo.botEscalatedAt) {
222	      await checkEscalationTimeout(convo.id);
223	      return;
224	    }
225	
226	    // Guardrail: per-conversation reply cap → escalate instead of looping.
227	    const botCount = convo.messages.filter((m) => m.sender === "bot").length;
228	    const maxReplies = await getSettingInt("kb_bot_max_replies", 16);
229	    if (maxReplies > 0 && botCount >= maxReplies) {
230	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
231	      return;
232	    }
233	
234	    // Guardrail: platform-wide daily reply cap (soft cost ceiling). Over it, we
235	    // still answer — just from the token-free retrieval path (no paid call).
236	    let overDaily = false;
237	    const dailyCap = await getSettingInt("kb_bot_daily_cap", 1000);
238	    if (dailyCap > 0) {
239	      const since = new Date();
240	      since.setHours(0, 0, 0, 0);
241	      const used = await db.kbBotLog.count({
242	        where: { createdAt: { gte: since }, kind: { in: ["answer", "offer"] } },
243	      });
244	      overDaily = used >= dailyCap;
245	    }
246	
247	    const history = toHistory(convo.messages.slice(0, -1));
248	    const result = await kbAnswer(args.currentBody, {
249	      history,
250	      images: args.images,
251	      visitorName: firstName(convo.name),
252	      userId: convo.userId,
253	      noLlm: overDaily,
254	      conversationId: convo.id,
255	    });
256	
257	    // A live agent is ONLY brought in when the visitor explicitly asks for one
258	    // (humanIntent → kind "handoff"). The bot never offers or escalates on its own.
259	    if (result.kind === "handoff") {
260	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
261	      return;
262	    }
263	
264	    if (result.reply) {
265	      // Resolve any plan cards to render with this reply: the LLM signals them
266	      // with a hidden [[cards: key1, key2]] directive; the retrieval fallback
267	      // supplies result.cardKeys. Cards are looked up from the real catalog, so
268	      // the model can only ever pick keys — prices/features are never invented.
269	      const parsedCards = parseCardDirective(result.reply);
270	      // Account-action cards are the same mechanism's sibling: [[action: ...]]
271	      // directives, resolved against THIS customer's own data (never invented —
272	      // see resolveActionCard's ownership checks). Parsed from whatever text
273	      // parseCardDirective left behind, so both directives can coexist.
274	      const parsedActions = parseActionDirectives(parsedCards.body);
275	      const keys = [...(result.cardKeys ?? []), ...parsedCards.keys];
276	      const planCards: ChatCard[] = keys.length
277	        ? getPlanCards(keys).map((c) => ({ ...c, type: "plan" as const }))
278	        : [];
279	      const actionCards = (
280	        await Promise.all(
281	          parsedActions.specs
282	            .slice(0, 3) // never render a wall of cards
283	            .map((spec) => resolveActionCard(convo.userId, spec.kind, spec.id, spec.label)),
284	        )
285	      ).filter((c): c is AccountActionCard => c !== null);
286	      const cards: ChatCard[] = [...planCards, ...actionCards];
287	      await db.chatMessage.create({
288	        data: {
289	          conversationId: convo.id,
290	          sender: "bot",
291	          body: parsedActions.body,
292	          cardsJson: cards.length ? JSON.stringify(cards) : null,
293	        },
294	      });
295	    }
296	    // Log coverage. A HARD model failure (bad/unfunded key, API outage) is logged
297	    // as "llm_error" — distinct from an expected "degraded"/over-cap — so the
298	    // admin KB dashboard shows the bot is broken instead of it failing silently.
299	    await db.kbBotLog
300	      .create({
301	        data: {
302	          visitorId: args.visitorId,
303	          conversationId: convo.id,
304	          question: args.currentBody.slice(0, 500),
305	          kind: result.llmFailure === "error" ? "llm_error" : result.kind,
306	          matchedTitle: result.matchedTitle ?? null,
307	        },
308	      })
309	      .catch(() => {});
310	  } catch {
311	    /* assistant is non-essential — never fail the visitor's message on it */
312	  }
313	}
