12	/**
13	 * Public live-chat endpoint used by <ChatWidget/>.
14	 *
15	 * POST /api/chat  — start or continue a conversation for a visitorId.
16	 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
17	 *
18	 * Everything is scoped strictly by the client-supplied `visitorId`; we never
19	 * return another visitor's data. Signed-in customers additionally get their
20	 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
21	 * POST path is rate-limited per IP.
22	 */
23	
24	function clip(v: unknown, max: number): string | null {
25	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
26	}
27	
28	type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;
29	
30	function serialize(convo: {
31	  id: string;
32	  status: string;
33	  name: string | null;
34	  email: string | null;
35	  messages: {
36	    id: string;
37	    sender: string;
38	    body: string;
39	    cardsJson?: string | null;
40	    createdAt: Date;
41	    attachment?: AttachmentRow;
42	  }[];
43	}) {
44	  return {
45	    conversation: {
46	      id: convo.id,
47	      status: convo.status,
48	      name: convo.name,
49	      email: convo.email,
50	    },
51	    messages: convo.messages.map((m) => {
52	      let cards: unknown = null;
53	      if (m.cardsJson) {
54	        try {
55	          cards = JSON.parse(m.cardsJson);
56	        } catch {
57	          cards = null;
58	        }
59	      }
60	      return {
61	        id: m.id,
62	        sender: m.sender,
63	        body: m.body,
64	        createdAt: m.createdAt.toISOString(),
65	        cards,
66	        attachment: m.attachment
67	          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
68	          : null,
69	      };
70	    }),
71	  };
72	}
