74	export async function POST(req: Request) {
75	  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
76	  if (!rl.ok) {
77	    return NextResponse.json(
78	      { error: "Too many messages. Please slow down." },
79	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
80	    );
81	  }
82	
83	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
84	  const visitorId = clip(raw.visitorId, 100);
85	  const conversationId = clip(raw.conversationId, 40);
86	  const body = clip(raw.body, 5000);
87	  const name = clip(raw.name, 120);
88	  const email = clip(raw.email, 200);
89	
90	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
91	  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });
92	
93	  const user = await currentUser();
94	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
95	    user?.id ? [{ userId: user.id }] : [],
96	  );
97	
98	  // If the client names a conversation it owns, continue it (resuming past
99	  // history, reopening if it was closed). Otherwise start a brand-new one — we
100	  // no longer auto-resume the latest, so returning gives a fresh chat while old
101	  // threads stay available in the history list.
102	  let convo = conversationId
103	    ? await db.chatConversation.findFirst({
104	        where: { id: conversationId, OR: ownedBy },
105	        select: { id: true, name: true, email: true },
106	      })
107	    : null;
108	
109	  if (!convo) {
110	    // Anonymous (not signed in) visitors must give a name + valid email before
111	    // starting. Signed-in customers already have both, so they're never asked.
112	    if (!user) {
113	      const nm = name ?? null;
114	      const em = email ?? null;
115	      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
116	        return NextResponse.json(
117	          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
118	          { status: 400 },
119	        );
120	      }
121	    }
122	    convo = await db.chatConversation.create({
123	      data: {
124	        visitorId,
125	        userId: user?.id ?? null,
126	        name: name ?? user?.name ?? null,
127	        email: email ?? user?.email ?? null,
128	      },
129	      select: { id: true, name: true, email: true },
130	    });
131	  }
132	
133	  await db.$transaction([
134	    db.chatMessage.create({
135	      data: { conversationId: convo.id, sender: "visitor", body },
136	    }),
137	    db.chatConversation.update({
138	      where: { id: convo.id },
139	      data: {
140	        status: "OPEN", // reopen if the visitor is resuming a closed thread
141	        unreadForAgent: true,
142	        lastMessageAt: new Date(),
143	        // Backfill identity / link account if it arrives after creation.
144	        ...(user?.id ? { userId: user.id } : {}),
145	        ...(name && !convo.name ? { name } : {}),
146	        ...(email && !convo.email ? { email } : {}),
147	      },
148	    }),
149	  ]);
150	
151	  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
152	  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
153	  // human has engaged.
154	  try {
155	    const { runAssistant } = await import("@/lib/kb-run");
156	    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
157	  } catch {
158	    /* assistant is non-essential — never fail the visitor's message on it */
159	  }
160	
161	  const full = await db.chatConversation.findUnique({
162	    where: { id: convo.id },
163	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
164	  });
165	  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
166	}
