168	export async function GET(req: Request) {
169	  const url = new URL(req.url);
170	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
171	  const conversationId = clip(url.searchParams.get("conversationId"), 40);
172	  if (!visitorId) {
173	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
174	  }
175	
176	  const user = await currentUser();
177	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
178	    user?.id ? [{ userId: user.id }] : [],
179	  );
180	
181	  // Poll a specific conversation when named (scoped to the visitor/user), else
182	  // the most recent open thread for back-compat.
183	  let convo = conversationId
184	    ? await db.chatConversation.findFirst({
185	        where: { id: conversationId, OR: ownedBy },
186	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
187	      })
188	    : await db.chatConversation.findFirst({
189	        where: { visitorId, status: "OPEN" },
190	        orderBy: { lastMessageAt: "desc" },
191	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
192	      });
