198	  // If the bot is waiting on a live agent, let the poll drive the handoff window:
199	  // post the "no agents available" fallback once it elapses, then refresh so the
200	  // visitor sees it on this same poll rather than the next one.
201	  if (convo.botEscalatedAt) {
202	    try {
203	      const { checkEscalationTimeout } = await import("@/lib/kb-run");
204	      await checkEscalationTimeout(convo.id);
205	      const refreshed = await db.chatConversation.findFirst({
206	        where: { id: convo.id },
207	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
208	      });
209	      if (refreshed) convo = refreshed;
210	    } catch {
211	      /* non-essential */
212	    }
213	  }
214	
215	  // Reading the thread clears the visitor-facing unread flag.
216	  if (convo.unreadForUser) {
217	    await db.chatConversation
218	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
219	      .catch(() => {});
220	  }
