  subject   String
  status    TicketStatus    @default(OPEN)
  priority  TicketPriority  @default(NORMAL)
  userId    String
  user      User            @relation(fields: [userId], references: [id], onDelete: Cascade)
  messages  TicketMessage[]
  createdAt DateTime        @default(now())
  updatedAt DateTime        @updatedAt

  // Discord support bridge (lib/discord-bridge.ts): the id of the private-guild
  // text channel mirroring this ticket, so a re-opened/replied ticket posts into
  // the SAME channel instead of creating a new one each time. Null until the
  // bridge first mirrors this ticket (or always null while discord_enabled is
  // off / the bridge fails — best-effort, never blocks ticket creation).
  //
  // NOT YET PUSHED to the live database — this worktree deliberately did not
  // run `prisma db push` (or regenerate the shared Prisma Client, which is
  // symlinked into the live /opt/nxeon node_modules) against the real, shared
  // Postgres instance, to avoid the running production app requesting a column
  // that does not exist yet. Run `npx prisma db push` (then `npx prisma
  // generate`) for real once this branch is reviewed and ready to promote —
  // see lib/discord-bridge.ts, which reads/writes this field via an explicit
  // unchecked cast until then.
  discordThreadId String?
}

  botEscalatedAt DateTime?
  messages       ChatMessage[]

  // Discord support bridge (lib/discord-bridge.ts): same purpose and same
  // "not yet pushed" caveat as Ticket.discordThreadId above — see that field's
  // doc comment for the full explanation. Read/written via an explicit
  // unchecked cast in lib/discord-bridge.ts until a real `prisma db push` +
  // `generate` runs for this branch.
  discordThreadId String?

  @@index([status, lastMessageAt])
  @@index([visitorId])
}

  renewals_paypal_fallback_enabled: "false",

  // --- Discord support bridge (Phase 1 mirror + simplified Phase 2 reply) ---
  //
  // A real Discord application is already configured (bot username "Nxeon
  // Support", private guild "Nxeon Cloud") — these four rows already exist in
  // the live `Setting` table with real values; the defaults below only matter
  // for a from-scratch environment. See lib/discord.ts for the REST client and
  // lib/discord-bridge.ts for the mirror/reply logic.
  discord_application_id: "",
  discord_public_key: "",
  // ENCRYPTED (encryptSecret/decryptSecret, same as kb_bot_api_key) — see
  // lib/discord.ts's botToken() for the decrypt-on-read.
  discord_bot_token: "",
  discord_guild_id: "",
  // MASTER KILL-SWITCH. Default FALSE so this ships dark: every mirror call in
  // lib/discord-bridge.ts checks this FIRST and no-ops silently when off (never
  // throws, never blocks a ticket/chat write — see the file's top-of-file
  // comment). The owner flips this true only after reviewing the bridge in the
  // real (currently empty) "Nxeon Cloud" guild.
  discord_enabled: "false",
  // Which Nxeon User.id a Discord-originated reply (via the Reply button/modal)
  // is attributed to as TicketMessage.authorId / the chat equivalent. Left
  // UNSET on purpose — this is a real admin/owner User.id and must never be
  // guessed or hardcoded. While empty, lib/discord-bridge.ts's reply path
  // refuses loudly (logs + posts a visible "⚠️ Discord replies aren't
  // configured yet" message back into the Discord thread) instead of silently
  // failing or attributing to a null/fake user. This is the deliberate
  // single-person-only simplification for this build: only whoever is
  // configured here can ever have a Discord reply attributed to them — see
  // lib/discord-bridge.ts's top-of-file comment for why that is an acceptable
  // stand-in for real auth on this one webhook path (Discord's own Ed25519
  // signature verification is the actual authentication; this setting is
  // attribution, not access control).
  discord_reply_as_user_id: "",
} as const;

