import { generateKeyPairSync, sign, verify, createPublicKey } from "node:crypto";

const { publicKey, privateKey } = generateKeyPairSync("ed25519");

// Raw 32-byte public key, the format Discord gives us (hex string).
const rawPub = publicKey.export({ type: "spki", format: "der" }).subarray(-32);
const rawPubHex = rawPub.toString("hex");
console.log("raw pub hex len", rawPubHex.length);

// Approach: reconstruct SPKI DER from the known Ed25519 prefix + raw key.
const ED25519_SPKI_PREFIX = Buffer.from("302a300506032b6570032100", "hex");
function publicKeyFromHex(hex) {
  const raw = Buffer.from(hex, "hex");
  if (raw.length !== 32) throw new Error("bad length");
  return createPublicKey({ key: Buffer.concat([ED25519_SPKI_PREFIX, raw]), format: "der", type: "spki" });
}

const reconstructed = publicKeyFromHex(rawPubHex);

const message = Buffer.from("1700000000" + JSON.stringify({ type: 1 }));
const signature = sign(null, message, privateKey);

const ok = verify(null, message, reconstructed, signature);
console.log("verify ok:", ok);

const tampered = Buffer.concat([message, Buffer.from("x")]);
const bad = verify(null, tampered, reconstructed, signature);
console.log("verify tampered (should be false):", bad);

// Also test JWK approach for comparison
const jwkKey = createPublicKey({
  key: { kty: "OKP", crv: "Ed25519", x: rawPub.toString("base64url") },
  format: "jwk",
});
const ok2 = verify(null, message, jwkKey, signature);
console.log("verify via jwk ok:", ok2);
EOF
node ./__ed25519_test.mjs
