import "server-only";
import { createPublicKey, verify as cryptoVerify } from "node:crypto";
import { getSetting, getSettingBool } from "./settings";
import { decryptSecret } from "./crypto-box";

/**
 * Thin Discord REST + Interactions-verification layer for the Nxeon support
 * bridge (lib/discord-bridge.ts). Deliberately NOT a discord.js Gateway
 * client and NOT a long-running process: this bot only ever (a) makes plain
 * REST calls the platform's own server code triggers, and (b) answers
 * Discord's HTTP "Interactions Endpoint" POSTs (button clicks, modal
 * submits) via app/api/webhooks/discord/route.ts. See the research this
 * build executed: an HTTP-only bot is the right shape for this codebase's
 * existing poll/request-response architecture, and Discord forum channels
 * cannot have private threads anyway (irrelevant here since the bridge uses
 * plain text channels — see lib/discord-bridge.ts for that call).
 *
 * Every config value is read via getSetting/getSettingBool/decryptSecret —
 * NEVER a bare process.env.DISCORD_* — except as a secondary fallback
 * mirroring the exact convention lib/kb-llm.ts's resolveBotKey() already
 * established for kb_bot_api_key.
 */

const DISCORD_API_BASE = "https://discord.com/api/v10";

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

export async function discordEnabled(): Promise<boolean> {
  return getSettingBool("discord_enabled", false);
}

export async function discordApplicationId(): Promise<string> {
  const v = (await getSetting("discord_application_id", "")).trim();
  return v || (process.env.DISCORD_APPLICATION_ID ?? "").trim();
}

export async function discordGuildId(): Promise<string> {
  const v = (await getSetting("discord_guild_id", "")).trim();
  return v || (process.env.DISCORD_GUILD_ID ?? "").trim();
}

export async function discordPublicKey(): Promise<string> {
  const v = (await getSetting("discord_public_key", "")).trim();
  return v || (process.env.DISCORD_PUBLIC_KEY ?? "").trim();
}

/** Decrypt-on-read, mirroring lib/kb-llm.ts's resolveBotKey() exactly. */
export async function discordBotToken(): Promise<string | null> {
  const enc = await getSetting("discord_bot_token", "");
  const own = decryptSecret(enc || null);
  if (own && own.trim()) return own.trim();
  const platform = process.env.DISCORD_BOT_TOKEN;
  return platform && platform.trim() ? platform.trim() : null;
}

/** The configured Nxeon User.id Discord-originated replies attribute to. Empty = unset. */
export async function discordReplyAsUserId(): Promise<string> {
  return (await getSetting("discord_reply_as_user_id", "")).trim();
}

// ---------------------------------------------------------------------------
// Ed25519 interaction-signature verification
// ---------------------------------------------------------------------------

// The fixed 12-byte ASN.1 prefix for an Ed25519 SubjectPublicKeyInfo (SPKI)
// DER structure — "SEQUENCE { SEQUENCE { OID 1.3.101.112 } BIT STRING }".
// Discord (like most Ed25519 key issuers) hands out only the raw 32-byte
// public key as hex; Node's `crypto.createPublicKey` needs a full SPKI DER
// blob to build a KeyObject, and this prefix is constant for every Ed25519
// key, so prepending it to the raw 32 bytes reconstructs a valid SPKI DER
// value Node can parse. Verified against Node 22's `node:crypto` directly
// (generateKeyPairSync("ed25519") → export raw pub → reconstruct via this
// prefix → verify() succeeds and correctly rejects a tampered payload).
const ED25519_SPKI_DER_PREFIX = Buffer.from("302a300506032b6570032100", "hex");

function ed25519PublicKeyFromHex(hex: string) {
  const raw = Buffer.from(hex, "hex");
  if (raw.length !== 32) throw new Error(`Discord public key must decode to 32 bytes, got ${raw.length}`);
  return createPublicKey({
    key: Buffer.concat([ED25519_SPKI_DER_PREFIX, raw]),
    format: "der",
    type: "spki",
  });
}

/**
 * Verify a Discord Interactions Endpoint request. Discord signs
 * `timestamp + rawBody` with Ed25519 and sends the signature + timestamp as
 * headers; this MUST be checked against the raw (pre-JSON-parse) request body
 * before trusting anything in it. Returns false on ANY problem (missing
 * headers, malformed hex, wrong-length key, bad signature, tampered body) —
 * never throws, so callers can treat "false" as the single "reject with 401"
 * signal.
 */
export function verifyDiscordSignature(args: {
  rawBody: string;
  signature: string | null | undefined;
  timestamp: string | null | undefined;
  publicKeyHex: string;
}): boolean {
  const { rawBody, signature, timestamp, publicKeyHex } = args;
  if (!signature || !timestamp || !publicKeyHex) return false;
  try {
    if (!/^[0-9a-f]+$/i.test(signature) || !/^[0-9a-f]+$/i.test(publicKeyHex)) return false;
    const key = ed25519PublicKeyFromHex(publicKeyHex);
    const message = Buffer.from(timestamp + rawBody, "utf8");
    const sig = Buffer.from(signature, "hex");
    return cryptoVerify(null, message, key, sig);
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// REST client
// ---------------------------------------------------------------------------

export class DiscordApiError extends Error {
  constructor(
    public status: number,
    public body: unknown,
  ) {
    super(`Discord API ${status}: ${typeof body === "string" ? body : JSON.stringify(body)}`);
  }
}

/**
 * Bot-authenticated REST call. Respects a single 429 retry (Discord's rate
 * limits are generous at this volume — 50 req/s global — so anything beyond
 * one retry would indicate a real problem, not routine throttling). Returns
 * `null` (never throws) when the bot token isn't configured, so every caller
 * in lib/discord-bridge.ts can stay a best-effort no-op.
 */
export async function discordFetch(
  path: string,
  init: { method?: string; body?: unknown; retried?: boolean } = {},
): Promise<{ status: number; json: unknown } | null> {
  const token = await discordBotToken();
  if (!token) {
    console.error("[discord] no bot token configured — cannot call", path);
    return null;
  }
  const res = await fetch(`${DISCORD_API_BASE}${path}`, {
    method: init.method ?? "GET",
    headers: {
      Authorization: `Bot ${token}`,
      "Content-Type": "application/json",
    },
    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
  });

  if (res.status === 429 && !init.retried) {
    const retryAfterSec = Number(res.headers.get("Retry-After") ?? "1") || 1;
    await new Promise((r) => setTimeout(r, Math.min(retryAfterSec, 5) * 1000));
    return discordFetch(path, { ...init, retried: true });
  }

  const text = await res.text();
  let json: unknown = null;
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      json = text;
    }
  }
  return { status: res.status, json };
}

// ---------------------------------------------------------------------------
// Typed helpers
// ---------------------------------------------------------------------------

/** Discord channel type 0 = GUILD_TEXT. */
const GUILD_TEXT_CHANNEL_TYPE = 0;

export async function createGuildTextChannel(name: string, topic?: string): Promise<string | null> {
  const guildId = await discordGuildId();
  if (!guildId) {
    console.error("[discord] no guild id configured — cannot create channel");
    return null;
  }
  // Discord channel names: lowercase, hyphens, max 100 chars, no spaces.
  const safeName = name
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 90) || "ticket";

  const res = await discordFetch(`/guilds/${guildId}/channels`, {
    method: "POST",
    body: {
      name: safeName,
      type: GUILD_TEXT_CHANNEL_TYPE,
      topic: topic?.slice(0, 1024),
    },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] createGuildTextChannel failed", res?.status, res?.json);
    return null;
  }
  return (res.json as { id: string }).id;
}

/** A button (type 2) inside a single action row (type 1), Reply style. */
function replyButtonRow(customId: string, label = "Reply"): unknown {
  return {
    type: 1,
    components: [{ type: 2, style: 1, label, custom_id: customId }],
  };
}

/** Post a plain message, optionally with a Reply button. */
export async function postChannelMessage(
  channelId: string,
  content: string,
  opts: { replyButtonCustomId?: string } = {},
): Promise<boolean> {
  const res = await discordFetch(`/channels/${channelId}/messages`, {
    method: "POST",
    body: {
      content: content.slice(0, 2000), // Discord message content cap
      components: opts.replyButtonCustomId ? [replyButtonRow(opts.replyButtonCustomId)] : undefined,
    },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] postChannelMessage failed", channelId, res?.status, res?.json);
    return false;
  }
  return true;
}

export async function getChannel(channelId: string): Promise<{ id: string; name: string } | null> {
  const res = await discordFetch(`/channels/${channelId}`);
  if (!res || res.status >= 300) return null;
  return res.json as { id: string; name: string };
}

export async function deleteChannel(channelId: string): Promise<boolean> {
  const res = await discordFetch(`/channels/${channelId}`, { method: "DELETE" });
  return Boolean(res && res.status < 300);
}

// ---------------------------------------------------------------------------
// Interaction response helpers (used by app/api/webhooks/discord/route.ts)
// ---------------------------------------------------------------------------

/** Interaction type constants (Discord API v10). */
export const InteractionType = {
  PING: 1,
  APPLICATION_COMMAND: 2,
  MESSAGE_COMPONENT: 3,
  APPLICATION_COMMAND_AUTOCOMPLETE: 4,
  MODAL_SUBMIT: 5,
} as const;

/** Interaction callback type constants. */
export const InteractionCallbackType = {
  PONG: 1,
  CHANNEL_MESSAGE_WITH_SOURCE: 4,
  MODAL: 9,
} as const;

/** Build the modal-open response body for a "Reply" button click. */
export function replyModalResponse(customId: string, title = "Reply to customer") {
  return {
    type: InteractionCallbackType.MODAL,
    data: {
      custom_id: customId,
      title,
      components: [
        {
          type: 1,
          components: [
            {
              type: 4, // TEXT_INPUT
              custom_id: "reply_text",
              style: 2, // paragraph
              label: "Your reply",
              required: true,
              max_length: 4000,
            },
          ],
        },
      ],
    },
  };
}

/** Build a simple, visible channel-message acknowledgement response body. */
export function channelMessageResponse(content: string) {
  return {
    type: InteractionCallbackType.CHANNEL_MESSAGE_WITH_SOURCE,
    data: { content: content.slice(0, 2000) },
  };
}

/** Extract the single text-input value from a MODAL_SUBMIT interaction payload. */
export function extractModalText(interaction: unknown): string {
  try {
    const data = (interaction as { data?: { components?: unknown[] } }).data;
    const row = data?.components?.[0] as { components?: { value?: unknown }[] } | undefined;
    const value = row?.components?.[0]?.value;
    return typeof value === "string" ? value : "";
  } catch {
    return "";
  }
}

import "server-only";
import { db } from "./db";
import {
  discordEnabled,
  discordReplyAsUserId,
  createGuildTextChannel,
  postChannelMessage,
} from "./discord";
import { writeTicketReply, writeChatReply } from "./reply-core";

/**
 * Nxeon Discord support bridge — Phase 1 (mirror) + a deliberately simplified
 * Phase 2 (reply round-trip), scoped to the owner's OWN PERSONAL USE right now
 * (get a phone push notification when a ticket/chat comes in; reply from
 * Discord and have it really reach the customer). NOT the eventual multi-staff
 * version — there is no Discord-account-to-Nxeon-user identity linking here,
 * on purpose; that's deferred until real support staff join.
 *
 * SHAPE: one plain text channel per ticket / chat conversation in a single,
 * private guild ("Nxeon Cloud", one member: the owner). Text channel, not a
 * forum-with-threads: forum channels cannot have PRIVATE threads in Discord's
 * current API, and since this whole guild is private and single-member,
 * "private within the guild" isn't a requirement anyway — a plain channel per
 * ticket is simpler to create/list/delete via REST and needs no thread
 * bookkeeping. See lib/discord.ts for the REST client and Ed25519 signature
 * verification, and app/api/webhooks/discord/route.ts for the Interactions
 * Endpoint that handles the Reply button + modal.
 *
 * ATTRIBUTION, NOT AUTHENTICATION. `submitDiscordReply` below attributes every
 * Discord-originated reply to the single Nxeon User.id configured in the
 * `discord_reply_as_user_id` setting. That is a deliberate simplification: the
 * real access control is Discord's own guild membership (only the owner is in
 * this private guild) plus this webhook's Ed25519 signature verification
 * (nothing reaches this code without both). There is no second staff member to
 * distinguish yet, so a single configured user id is the whole "who is this"
 * question this build needs to answer. When actual support staff join later,
 * this is the seam to replace with real per-Discord-user identity linking —
 * do NOT bolt that on here without designing it properly.
 *
 * KILL-SWITCH DISCIPLINE: every exported function below checks
 * `discordEnabled()` FIRST and returns silently if it's off, and every DB/REST
 * call is wrapped so a Discord outage or misconfiguration can NEVER throw back
 * into a ticket/chat write path — matching this codebase's established
 * best-effort third-party-integration pattern (see how `sendMail` failures are
 * handled in lib/reply-core.ts).
 *
 * SCHEMA CAVEAT: `Ticket.discordThreadId` / `ChatConversation.discordThreadId`
 * are NOT YET pushed to the live database (see the doc comments on those
 * fields in prisma/schema.prisma) — every read/write of them here goes through
 * an explicit `as any`/unchecked cast until a real `prisma db push` +
 * `generate` runs for this branch.
 */

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

// ---------------------------------------------------------------------------
// custom_id encoding — shared vocabulary between the message Reply button, the
// modal opened in response to it, and the webhook route that parses both.
// ---------------------------------------------------------------------------

export type BridgeKind = "ticket" | "chat";

function isBridgeKind(v: string): v is BridgeKind {
  return v === "ticket" || v === "chat";
}

export function replyButtonCustomId(kind: BridgeKind, id: string): string {
  return `dc_reply:${kind}:${id}`;
}

export function replyModalCustomId(kind: BridgeKind, id: string): string {
  return `dc_reply_modal:${kind}:${id}`;
}

/** Parse a `dc_reply:<kind>:<id>` or `dc_reply_modal:<kind>:<id>` custom_id. */
export function parseBridgeCustomId(
  customId: string,
): { action: "reply" | "reply_modal"; kind: BridgeKind; id: string } | null {
  const parts = customId.split(":");
  if (parts.length !== 3) return null;
  const [prefix, kindRaw, id] = parts;
  if (!id) return null;
  if (!isBridgeKind(kindRaw)) return null;
  if (prefix === "dc_reply") return { action: "reply", kind: kindRaw, id };
  if (prefix === "dc_reply_modal") return { action: "reply_modal", kind: kindRaw, id };
  return null;
}

// ---------------------------------------------------------------------------
// Ticket mirror
// ---------------------------------------------------------------------------

type TicketForChannel = { id: string; subject: string; priority: string; userId: string };

/** Create the ticket's Discord channel + post the opening context message if
 *  it doesn't have one yet; return the (existing or new) channel id. */
async function ensureTicketChannel(ticket: TicketForChannel & { discordThreadId?: string | null }): Promise<string | null> {
  const existing = (ticket as { discordThreadId?: string | null }).discordThreadId;
  if (existing) return existing;

  const user = await db.user.findUnique({ where: { id: ticket.userId }, select: { name: true, email: true } });
  const channelId = await createGuildTextChannel(
    `ticket-${ticket.id.slice(-8)}`,
    `Ticket ${ticket.id}: ${ticket.subject}`.slice(0, 1024),
  );
  if (!channelId) return null;

  await postChannelMessage(
    channelId,
    [
      "🎫 **New support ticket**",
      `**Subject:** ${ticket.subject}`,
      `**Priority:** ${ticket.priority}`,
      `**Customer:** ${user?.name ?? "?"}${user?.email ? ` (${user.email})` : ""}`,
      `**Admin:** ${APP_URL}/admin/support/${ticket.id}`,
    ].join("\n"),
  );

  await db.ticket.update({ where: { id: ticket.id }, data: { discordThreadId: channelId } as never });
  return channelId;
}

/** Mirror a brand-new ticket (called right after `db.ticket.create`). */
export async function mirrorNewTicketToDiscord(ticketId: string): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const ticket = await db.ticket.findUnique({
      where: { id: ticketId },
      include: { messages: { orderBy: { createdAt: "asc" }, take: 1 } },
    });
    if (!ticket) return;
    const channelId = await ensureTicketChannel(ticket);
    if (!channelId) return;
    const firstMessage = ticket.messages[0];
    if (firstMessage) {
      await postChannelMessage(channelId, `👤 **Customer:** ${firstMessage.body}`, {
        replyButtonCustomId: replyButtonCustomId("ticket", ticket.id),
      });
    }
  } catch (e) {
    console.error("[discord-bridge] mirrorNewTicketToDiscord failed (non-fatal)", ticketId, e);
  }
}

/** Mirror a reply on an EXISTING ticket (staff or customer) into its channel,
 *  creating the channel first if this ticket predates the bridge (or its
 *  earlier mirror attempt failed). */
export async function mirrorTicketReplyToDiscord(ticketId: string, body: string, isStaffMessage: boolean): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
    if (!ticket) return;
    const channelId = await ensureTicketChannel(ticket);
    if (!channelId) return;
    const label = isStaffMessage ? "🛟 **Staff**" : "👤 **Customer**";
    await postChannelMessage(channelId, `${label}: ${body}`, {
      replyButtonCustomId: replyButtonCustomId("ticket", ticketId),
    });
  } catch (e) {
    console.error("[discord-bridge] mirrorTicketReplyToDiscord failed (non-fatal)", ticketId, e);
  }
}

// ---------------------------------------------------------------------------
// Chat mirror
// ---------------------------------------------------------------------------

type ConvoForChannel = { id: string; name: string | null; email: string | null; userId: string | null };

async function ensureChatChannel(convo: ConvoForChannel & { discordThreadId?: string | null }): Promise<string | null> {
  const existing = (convo as { discordThreadId?: string | null }).discordThreadId;
  if (existing) return existing;

  const who = convo.name
    ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
    : convo.email || "Anonymous visitor";
  const channelId = await createGuildTextChannel(
    `chat-${convo.id.slice(-8)}`,
    `Live chat ${convo.id}: ${who}`.slice(0, 1024),
  );
  if (!channelId) return null;

  await postChannelMessage(
    channelId,
    [
      "💬 **New live chat conversation**",
      `**Visitor:** ${who}`,
      `**Signed-in customer:** ${convo.userId ? "yes" : "no"}`,
      `**Admin inbox:** ${APP_URL}/admin/chat`,
    ].join("\n"),
  );

  await db.chatConversation.update({ where: { id: convo.id }, data: { discordThreadId: channelId } as never });
  return channelId;
}

/** Mirror one chat message (visitor OR agent) — handles both "first message of
 *  a new conversation" (creates the channel) and "message in an existing
 *  conversation" (posts into it) via the same discordThreadId check. */
export async function mirrorChatMessageToDiscord(
  conversationId: string,
  body: string,
  sender: "visitor" | "agent",
): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const convo = await db.chatConversation.findUnique({ where: { id: conversationId } });
    if (!convo) return;
    const channelId = await ensureChatChannel(convo);
    if (!channelId) return;
    const label = sender === "agent" ? "🛟 **Staff**" : "👤 **Visitor**";
    await postChannelMessage(channelId, `${label}: ${body}`, {
      replyButtonCustomId: replyButtonCustomId("chat", conversationId),
    });
  } catch (e) {
    console.error("[discord-bridge] mirrorChatMessageToDiscord failed (non-fatal)", conversationId, e);
  }
}

// ---------------------------------------------------------------------------
// Reply round-trip (Discord → Nxeon) — called by the modal-submit handler in
// app/api/webhooks/discord/route.ts. Returns the text to show back in Discord
// as the interaction's visible acknowledgement message.
// ---------------------------------------------------------------------------

const NOT_CONFIGURED_MSG =
  "⚠️ Discord replies aren't configured yet — set discord_reply_as_user_id in admin settings";

export async function submitDiscordReply(kind: BridgeKind, id: string, replyText: string): Promise<string> {
  const text = replyText.trim();
  if (!text) return "⚠️ Empty reply — nothing sent.";

  const replyAsUserId = await discordReplyAsUserId();
  if (!replyAsUserId) {
    console.error("[discord-bridge] reply attempted with discord_reply_as_user_id unset", { kind, id });
    return NOT_CONFIGURED_MSG;
  }

  try {
    if (kind === "ticket") {
      const result = await writeTicketReply({
        actorId: replyAsUserId,
        actorIsSupportStaff: true,
        ticketId: id,
        body: text,
      });
      if (result.error) return `⚠️ ${result.error}`;
      return "✅ Reply sent to the customer.";
    }

    const result = await writeChatReply({ conversationId: id, body: text, staffId: replyAsUserId });
    if (result.error) return `⚠️ ${result.error}`;
    return "✅ Reply sent to the customer.";
  } catch (e) {
    console.error("[discord-bridge] submitDiscordReply failed", kind, id, e);
    return "⚠️ Something went wrong sending that reply — check the admin panel.";
  }
}

import { NextResponse } from "next/server";
import {
  discordPublicKey,
  verifyDiscordSignature,
  InteractionType,
  replyModalResponse,
  channelMessageResponse,
  extractModalText,
} from "@/lib/discord";
import { parseBridgeCustomId, replyModalCustomId, submitDiscordReply } from "@/lib/discord-bridge";

export const runtime = "nodejs";

/**
 * Discord "Interactions Endpoint" webhook — the reply half of the support
 * bridge (see lib/discord-bridge.ts's top-of-file comment for the full
 * picture). Handles exactly three interaction shapes:
 *
 *   1. PING (type 1)              → PONG. Discord requires this before it will
 *                                    even save this URL in the Developer
 *                                    Portal, and it periodically re-sends PINGs
 *                                    (plus deliberately-invalid signatures) to
 *                                    keep testing the endpoint.
 *   2. MESSAGE_COMPONENT (type 3) → the "Reply" button under a mirrored
 *                                    message. Responds by opening a MODAL
 *                                    (type 9) — Discord requires the modal to
 *                                    be opened as the DIRECT response to the
 *                                    button click, not a follow-up call.
 *   3. MODAL_SUBMIT (type 5)      → the reply text the owner typed. Writes it
 *                                    through the shared reply-writing core
 *                                    (lib/reply-core.ts) and acknowledges with
 *                                    a visible confirmation/error message.
 *
 * Signature verification mirrors app/api/stripe/webhook/route.ts's pattern:
 * read the RAW body as text before any JSON parsing, verify a signature
 * header (Ed25519 here, HMAC there), and reject with a 4xx on any failure —
 * this is SECURITY CRITICAL. Every other interaction shape (slash commands,
 * autocomplete, …) is currently unused and gets a generic ack rather than an
 * error, since Discord expects SOME response.
 */
export async function POST(req: Request) {
  const rawBody = await req.text();
  const signature = req.headers.get("X-Signature-Ed25519");
  const timestamp = req.headers.get("X-Signature-Timestamp");
  const publicKeyHex = await discordPublicKey();

  if (!publicKeyHex) {
    console.error("[discord-webhook] no discord_public_key configured — rejecting");
    return NextResponse.json({ error: "not configured" }, { status: 401 });
  }

  const valid = verifyDiscordSignature({ rawBody, signature, timestamp, publicKeyHex });
  if (!valid) {
    return NextResponse.json({ error: "invalid request signature" }, { status: 401 });
  }

  let interaction: Record<string, unknown>;
  try {
    interaction = JSON.parse(rawBody);
  } catch {
    return NextResponse.json({ error: "invalid body" }, { status: 400 });
  }

  const type = interaction.type as number | undefined;

  // 1. PING — must be answered exactly like this or Discord refuses to save
  // the endpoint URL in the Developer Portal.
  if (type === InteractionType.PING) {
    return NextResponse.json({ type: 1 });
  }

  // 2. Button click ("Reply") — open the reply modal.
  if (type === InteractionType.MESSAGE_COMPONENT) {
    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
    const parsed = parseBridgeCustomId(customId);
    if (!parsed || parsed.action !== "reply") {
      return NextResponse.json(channelMessageResponse("Unrecognized button."));
    }
    return NextResponse.json(replyModalResponse(replyModalCustomId(parsed.kind, parsed.id)));
  }

  // 3. Modal submit — the owner's typed reply.
  if (type === InteractionType.MODAL_SUBMIT) {
    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
    const parsed = parseBridgeCustomId(customId);
    if (!parsed || parsed.action !== "reply_modal") {
      return NextResponse.json(channelMessageResponse("Unrecognized submission."));
    }
    const text = extractModalText(interaction);
    const ackText = await submitDiscordReply(parsed.kind, parsed.id, text);
    return NextResponse.json(channelMessageResponse(ackText));
  }

  // Any other interaction type (slash commands, autocomplete, …): none are
  // registered by this bridge, but Discord still expects a response.
  return NextResponse.json(channelMessageResponse("This interaction isn't handled."));
}

