import { test } from "node:test";
import assert from "node:assert/strict";
import { generateKeyPairSync, sign as cryptoSign } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { stripCommentsAndStrings } from "./_source-tools.ts";
import { verifyDiscordSignature } from "../lib/discord.ts";

/**
 * Ed25519 Interactions-Endpoint signature verification (lib/discord.ts's
 * `verifyDiscordSignature`) is SECURITY CRITICAL: it is the ONLY thing
 * standing between app/api/webhooks/discord/route.ts and an attacker who can
 * forge a "reply as the owner" request. This suite exercises it against a
 * REAL Ed25519 keypair generated by Node's own `node:crypto` — the exact
 * primitive the implementation uses — rather than trusting the
 * implementation by inspection alone.
 *
 * No network, no DB: `verifyDiscordSignature` is a pure function of its
 * arguments (rawBody/signature/timestamp/publicKeyHex).
 */

function keypair() {
  const { publicKey, privateKey } = generateKeyPairSync("ed25519");
  const rawPubHex = publicKey.export({ type: "spki", format: "der" }).subarray(-32).toString("hex");
  return { privateKey, publicKeyHex: rawPubHex };
}

function signDiscordStyle(privateKey: ReturnType<typeof generateKeyPairSync>["privateKey"], timestamp: string, rawBody: string) {
  const message = Buffer.from(timestamp + rawBody, "utf8");
  return cryptoSign(null, message, privateKey).toString("hex");
}

test("verifyDiscordSignature accepts a genuinely valid signature", () => {
  const { privateKey, publicKeyHex } = keypair();
  const timestamp = "1735000000";
  const rawBody = JSON.stringify({ type: 1 });
  const signature = signDiscordStyle(privateKey, timestamp, rawBody);

  assert.equal(verifyDiscordSignature({ rawBody, signature, timestamp, publicKeyHex }), true);
});

test("verifyDiscordSignature rejects a tampered body", () => {
  const { privateKey, publicKeyHex } = keypair();
  const timestamp = "1735000000";
  const rawBody = JSON.stringify({ type: 3, data: { custom_id: "dc_reply:ticket:abc123" } });
  const signature = signDiscordStyle(privateKey, timestamp, rawBody);

  const tamperedBody = JSON.stringify({ type: 3, data: { custom_id: "dc_reply:ticket:ATTACKER" } });
  assert.equal(
    verifyDiscordSignature({ rawBody: tamperedBody, signature, timestamp, publicKeyHex }),
    false,
    "a body that doesn't match what was signed must be rejected",
  );
});

test("verifyDiscordSignature rejects a tampered timestamp", () => {
  const { privateKey, publicKeyHex } = keypair();
  const rawBody = JSON.stringify({ type: 1 });
  const signature = signDiscordStyle(privateKey, "1735000000", rawBody);

  assert.equal(
    verifyDiscordSignature({ rawBody, signature, timestamp: "1735000001", publicKeyHex }),
    false,
    "the signed timestamp is part of the message — changing it must invalidate the signature",
  );
});

test("verifyDiscordSignature rejects a signature from the WRONG key", () => {
  const { privateKey } = keypair();
  const { publicKeyHex: wrongPublicKeyHex } = keypair(); // a different, unrelated keypair
  const timestamp = "1735000000";
  const rawBody = JSON.stringify({ type: 1 });
  const signature = signDiscordStyle(privateKey, timestamp, rawBody);

  assert.equal(verifyDiscordSignature({ rawBody, signature, timestamp, publicKeyHex: wrongPublicKeyHex }), false);
});

test("verifyDiscordSignature handles Discord's own periodic invalid-signature probes without throwing", () => {
  const { publicKeyHex } = keypair();
  const timestamp = "1735000000";
  const rawBody = JSON.stringify({ type: 1 });
  // Discord deliberately sends garbage signatures to test that an endpoint
  // rejects rather than crashes — a random hex string of the right length.
  const garbageSignature = "ab".repeat(64);

  assert.doesNotThrow(() => {
    const ok = verifyDiscordSignature({ rawBody, signature: garbageSignature, timestamp, publicKeyHex });
    assert.equal(ok, false);
  });
});

test("verifyDiscordSignature returns false (never throws) on missing headers", () => {
  const { publicKeyHex } = keypair();
  const rawBody = JSON.stringify({ type: 1 });
  assert.equal(verifyDiscordSignature({ rawBody, signature: null, timestamp: "1735000000", publicKeyHex }), false);
  assert.equal(verifyDiscordSignature({ rawBody, signature: "ab".repeat(64), timestamp: null, publicKeyHex }), false);
  assert.equal(verifyDiscordSignature({ rawBody, signature: undefined, timestamp: undefined, publicKeyHex }), false);
});

test("verifyDiscordSignature returns false (never throws) on malformed hex input", () => {
  const timestamp = "1735000000";
  const rawBody = JSON.stringify({ type: 1 });
  assert.doesNotThrow(() => {
    // Non-hex signature.
    assert.equal(
      verifyDiscordSignature({ rawBody, signature: "not-hex-at-all!!", timestamp, publicKeyHex: "aa".repeat(32) }),
      false,
    );
    // Non-hex public key.
    assert.equal(
      verifyDiscordSignature({ rawBody, signature: "ab".repeat(64), timestamp, publicKeyHex: "zz not hex zz" }),
      false,
    );
    // Public key that decodes to the wrong byte length (16 bytes, not 32).
    assert.equal(
      verifyDiscordSignature({ rawBody, signature: "ab".repeat(64), timestamp, publicKeyHex: "aa".repeat(16) }),
      false,
    );
    // Empty public key (as if the setting were never configured).
    assert.equal(verifyDiscordSignature({ rawBody, signature: "ab".repeat(64), timestamp, publicKeyHex: "" }), false);
  });
});

// ---------------------------------------------------------------------------
// SOURCE TRIPWIRES — the webhook route must verify BEFORE trusting anything
// in the body, must read the RAW body (not the parsed JSON) as the signed
// message, must answer PING, and must reject with a 4xx on bad signatures.
// Mirrors app/api/stripe/webhook/route.ts's established pattern.
// ---------------------------------------------------------------------------

function readSrc(rel: string): string {
  return stripCommentsAndStrings(readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8"));
}

test("the Discord webhook reads the RAW body as text before any JSON.parse", () => {
  const src = readSrc("../app/api/webhooks/discord/route.ts");
  const rawIdx = src.indexOf("req.text()");
  const parseIdx = src.indexOf("JSON.parse(rawBody)");
  assert.ok(rawIdx >= 0, "must read the raw body as text (the Ed25519-signed message)");
  assert.ok(parseIdx >= 0, "must JSON.parse the raw body for interaction handling");
  assert.ok(rawIdx < parseIdx, "the raw body must be captured BEFORE it is parsed as JSON");
});

test("the Discord webhook verifies the signature before parsing or trusting the body", () => {
  const src = readSrc("../app/api/webhooks/discord/route.ts");
  const verifyIdx = src.indexOf("verifyDiscordSignature(");
  const parseIdx = src.indexOf("JSON.parse(rawBody)");
  assert.ok(verifyIdx >= 0 && parseIdx >= 0);
  assert.ok(verifyIdx < parseIdx, "signature verification must happen before the body is parsed");
});

test("the Discord webhook rejects an invalid signature with a 4xx, never 2xx", () => {
  const src = readSrc("../app/api/webhooks/discord/route.ts");
  assert.match(src, /if\s*\(\s*!valid\s*\)\s*\{\s*return NextResponse\.json\([^)]*\{\s*status:\s*401\s*\}/s);
});

test("the Discord webhook answers PING (type 1) with PONG ({type: 1})", () => {
  const src = readSrc("../app/api/webhooks/discord/route.ts");
  assert.match(src, /type === InteractionType\.PING/);
  assert.match(src, /NextResponse\.json\(\{\s*type:\s*1\s*\}\)/, "must respond with the literal PONG shape {type: 1}");
});

import { createGuildTextChannel, postChannelMessage, getChannel, deleteChannel } from "./lib/discord.ts";

async function main() {
  console.log("Creating test channel in the real 'Nxeon Cloud' guild...");
  const channelId = await createGuildTextChannel("nxeon-bridge-smoke-test", "Automated smoke test — safe to ignore/delete");
  if (!channelId) {
    console.error("FAILED: createGuildTextChannel returned null");
    process.exit(1);
  }
  console.log("Created channel id:", channelId);

  console.log("Posting a test message with a Reply button...");
  const posted = await postChannelMessage(channelId, "🧪 Smoke test message from the Nxeon Discord bridge build.", {
    replyButtonCustomId: "dc_reply:ticket:smoketest123",
  });
  console.log("postChannelMessage ok:", posted);
  if (!posted) {
    console.error("FAILED: postChannelMessage returned false");
  }

  console.log("Reading the channel back via GET /channels/{id}...");
  const fetched = await getChannel(channelId);
  console.log("Fetched channel:", fetched);
  if (!fetched || fetched.id !== channelId) {
    console.error("FAILED: getChannel did not confirm the channel exists");
  }

  console.log("Deleting the test channel to leave the guild clean...");
  const deleted = await deleteChannel(channelId);
  console.log("deleteChannel ok:", deleted);

  console.log("Confirming deletion (getChannel should now fail)...");
  const afterDelete = await getChannel(channelId);
  console.log("getChannel after delete (should be null):", afterDelete);

  if (posted && fetched && deleted && !afterDelete) {
    console.log("\nSMOKE TEST PASSED");
  } else {
    console.log("\nSMOKE TEST HAD ISSUES — see above");
    process.exit(1);
  }
}

main().catch((e) => {
  console.error("SMOKE TEST THREW:", e);
  process.exit(1);
});

